from fastapi import APIRouter, status
from pydantic import BaseModel, EmailStr

router = APIRouter()
users: dict[str, dict] = {}

class UserCreate(BaseModel):
    name: str
    email: EmailStr

@router.post("/", status_code=status.HTTP_201_CREATED)
def create_user(payload: UserCreate):
    users[payload.email] = payload.model_dump()
    return users[payload.email]

CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL);
CREATE TABLE events (id INTEGER PRIMARY KEY, title TEXT NOT NULL);
CREATE TABLE registrations (user_id INTEGER NOT NULL, event_id INTEGER NOT NULL);
